{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When you say \"total overtime hours per month for the entire workforce cannot exceed 20 hours per worker,\" do you mean that each individual worker can work at most 20 overtime hours in a month (so total overtime is capped at 20 times the number of workers that month), or that the sum of all overtime hours across the whole workforce is capped at 20 hours total per month?"
  ],
  "rationale": "The response asks for a single policy clarification regarding the interpretation of the overtime cap, presenting two mutually exclusive options for one constraint."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When demand is back-ordered and fulfilled in a later month, is the sales revenue of 300 Yuan per unit recognized in the month the order was originally placed, or in the month the unit is actually delivered to the customer?"
  ],
  "rationale": "The response asks for a single policy choice regarding the timing of revenue recognition (order date vs. delivery date), which constitutes one semantically independent question."
}

