  "is_atomic": true,
  "atomic_questions": [
    "Can the workforce (number of employees) change from month to month through hiring and firing, or is the workforce fixed at 1,000 employees for all six months?"
  ],
  "rationale": "The response asks a single clarification question regarding whether the workforce size is variable or fixed."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When a worker is hired or fired in a given month, is that worker counted in the workforce for that same month (i.e., available to work regular and overtime hours in the month they are hired, and their regular wage is paid in that month), or do they only count starting the following month?"
  ],
  "rationale": "The response asks for a single policy choice regarding the timing of workforce inclusion for hires and fires, which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
