  "atomic_questions": [
    "Can the workforce go below 1,000 employees (i.e., can you fire workers down to fewer than the initial 1,000), or is 1,000 a minimum workforce level that must be maintained throughout the six months?"
  ],
  "rationale": "The response asks a single clarification question regarding the minimum workforce constraint, presenting two mutually exclusive options for the same policy decision."
}

